pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherCartel} from "../src/EtherCartel.sol";

contract InvMutTest is Test {
    EtherCartel c;
    function setUp() public { c = new EtherCartel(); }
    function testRegression_property() public {
        vm.deal(address(this), 1 ether);
        c.seedMarket{value: 1 ether}(1000000);

        address user = address(0x123);
        vm.deal(user, 1 ether);
        vm.prank(user);
        c.buyDrugs{value: 1 ether}();

        vm.prank(user);
        uint256 returnVal = c.calculateDrugSell(c.getMyDrugs());

        assertTrue(returnVal > 0);
    }
}
